    async def create_service_domain(
        self,
        *,
        exchange_service: str,
        name: str,
        organization_name: str,
        type_: EmailExchangeDomainTypeEnum,
        auto_enable_dkim: bool | None = None,
        configure_autodiscover: bool | None = None,
        configure_dkim: bool | None = None,
        configure_mx: bool | None = None,
        configure_spf: bool | None = None,
        main: bool | None = None,
        mx_relay: str | None = None,
        organization2010: str | None = None,
        sbr_default: str | None = None,
        send_connector_id_default: int | None = None,
    ) -> EmailExchangeTask:
        """
        POST /1.0/email/exchange/{organizationName}/service/{exchangeService}/domain

        Add a domain

        Args:
            auto_enable_dkim: Enable DKIM automatically after DKIM configuration
            configure_autodiscover: If you host domain in OVH we can configure
                autodiscover record automatically
            configure_dkim: Launch configuration of DKIM automatically for the domain
            configure_mx: If you host domain in OVH we can configure mx record
                automatically
            configure_spf: Enable automatic SPF record (only for domains hosted by
                OVHcloud)
            exchange_service: The internal name of your exchange service
            main: This newly created domain will be an organization (Exchange 2010 only)
            mx_relay: If specified, emails to not existing address will be redirected to
                that domain
            name: Domain to install on server
            organization2010: If specified, indicates which organization this newly
                created domain will be part of (Exchange 2010 only)
            organization_name: The internal name of your exchange organization
            sbr_default: Default Sender base routing destination domain applied on all
                new created accounts
            send_connector_id_default: Default Sender Connector id applied on all new
                created accounts
            type_: Type of domain that You want to install
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/1.0/email/exchange/{organizationName}/service/{exchangeService}/domain",
                exchangeService=exchange_service,
                organizationName=organization_name,
            ),
            body={
                "autoEnableDKIM": auto_enable_dkim,
                "configureAutodiscover": configure_autodiscover,
                "configureDKIM": configure_dkim,
                "configureMx": configure_mx,
                "configureSPF": configure_spf,
                "main": main,
                "mxRelay": mx_relay,
                "name": name,
                "organization2010": organization2010,
                "sbrDefault": sbr_default,
                "sendConnectorIdDefault": send_connector_id_default,
                "type": type_,
            },
        )
        return EmailExchangeTask.model_validate(data)

